import { StyleSheet, Text, View } from 'react-native';
import type { NativeStackScreenProps } from '@react-navigation/native-stack';

import type { RootStackParamList } from '../navigation/types';
import { Button } from '../components/Button';

type Props = NativeStackScreenProps<RootStackParamList, 'Home'>;

export default function HomeScreen({ navigation }: Props) {
  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Native Bench</Text>
        <Text style={styles.subtitle}>Token economics benchmark</Text>
      </View>
      <View style={styles.actions}>
        <Button label="Health" onPress={() => navigation.navigate('Health')} />
        <Button label="Transcribe" onPress={() => navigation.navigate('Transcribe')} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    padding: 24,
    gap: 48,
